public class Main {static int findSlot(int[] prices,int newPrice){if(prices==null)throw new IllegalArgumentException();int low=0,high=prices.length;while(low<high){int mid=low+(high-low)/2;if(prices[mid]<newPrice)low=mid+1;else high=mid;}return low;}public static void main(String[]args){System.out.println(findSlot(new int[]{100,200,300,500},400));System.out.println("Binary search: O(log n) time, O(1) extra space.");}}